package com.euvcraft.lithmod.mc;
import com.google.gson.*;import org.junit.jupiter.api.Test;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
/** T6 aliases still require actual resolvable native models/textures and localized names. */
class T6AssetResourceTest {
 static final Set<String> ITEMS=Set.of("memory_chip_t6","compute_chip_t6","nand_chip_t6","cpu_t6","dimm_t6","resist_t6","multipattern_light_source","multipattern_optics","multipattern_stage","multipattern_filtration","multipattern_metrology","thermal_test_coupon","assembly_scrap","electronic_grade_boule");
 static final Set<String> BLOCKS=Set.of("zone_refiner","zone_casing","zone_power_port","zone_operating_panel","zone_water_inlet","reflow_oven","reflow_casing","reflow_power_port","reflow_operating_panel","reflow_calibration_panel","scanner_multipatterning_module");
 private JsonObject json(String path)throws IOException {try(var in=getClass().getResourceAsStream(path)){assertNotNull(in,path);return JsonParser.parseReader(new InputStreamReader(in,StandardCharsets.UTF_8)).getAsJsonObject();}}
 private void model(String id,Set<String> seen)throws IOException {if(id.startsWith("minecraft:"))return;assertTrue(id.startsWith("lithmod:"),id);assertTrue(seen.add(id),"Cyclic model parent "+id);var data=json("/assets/lithmod/models/"+id.substring(8)+".json");if(data.has("parent"))model(data.get("parent").getAsString(),seen);if(data.has("textures"))for(var entry:data.getAsJsonObject("textures").entrySet()){String tex=entry.getValue().getAsString();if(tex.startsWith("lithmod:"))try(var png=getClass().getResourceAsStream("/assets/lithmod/textures/"+tex.substring(8)+".png")){assertNotNull(png,tex);var image=javax.imageio.ImageIO.read(png);assertNotNull(image,tex);assertTrue(image.getWidth()>0&&image.getHeight()>0,tex);}}}
 @Test void everyNewItemAndBlockHasResolvableModelAndName()throws Exception {var lang=json("/assets/lithmod/lang/en_us.json");var all=new HashSet<>(ITEMS);all.addAll(BLOCKS);for(var id:all){assertTrue(lang.has("item.lithmod."+id),id);var item=json("/assets/lithmod/items/"+id+".json");model(item.getAsJsonObject("model").get("model").getAsString(),new HashSet<>());if(BLOCKS.contains(id)){assertTrue(lang.has("block.lithmod."+id),id);json("/assets/lithmod/blockstates/"+id+".json");json("/data/lithmod/loot_table/blocks/"+id+".json");}}}
 @Test void assemblyRecipeCountsAndFamiliesRemainExplicit()throws Exception {var cpu=json("/data/lithmod/machine_recipes/cpu_t6.json");var dimm=json("/data/lithmod/machine_recipes/dimm_t6.json");assertEquals("reflow_oven",cpu.get("machine").getAsString());assertEquals(1,cpu.getAsJsonArray("ingredients").get(0).getAsJsonObject().get("count").getAsInt());assertEquals(4,dimm.getAsJsonArray("ingredients").get(0).getAsJsonObject().get("count").getAsInt());assertEquals("lithmod:compute_chip_t6",cpu.getAsJsonArray("ingredients").get(0).getAsJsonObject().get("item").getAsString());assertEquals("lithmod:memory_chip_t6",dimm.getAsJsonArray("ingredients").get(0).getAsJsonObject().get("item").getAsString());}
}
